  const importBrushPackageToDocument=raw=>{const pack=typeof raw==='string'?JSON.parse(raw):clone(raw),candidate=new BrushPresetRegistry();for(const existing of app.doc.brushPackages||[])importBrushPackage(existing,candidate);const result=importBrushPackage(pack,candidate);if(result.status==='REJECTED')throw new Error(`INK_BRUSH_PACKAGE_INVALID:${result.errors.join(',')}`);app.history.pushScoped('匯入 Brush Package',[['brushPackages']],()=>{app.doc.brushPackages=app.doc.brushPackages||[];app.doc.brushPackages.push(pack);});brushes=candidate;studio.brushes=candidate;return result;};
  reloadBrushPackages();
  const loadFixture=kind=>{const fixture=createFlowerSkeleton(kind),page=app.page();page.layers=[{id:id('layer'),name:'Recipe Input',kind:'regions',visible:true,locked:false,opacity:1,objects:[]}];page.activeLayerId=page.layers[0].id;page.regions=fixture.inputs;app.selection=[];studio.currentFixture=fixture;app.doc.title=`INK ${fixture.name}`;app.history.clear();app.spatialDirty=true;app.refreshAll();app.resetView();status(`${fixture.name}：${fixture.inputs.length} 個結構區域已載入`);return fixture;};
  const execute=(options={})=>{if(!studio.currentFixture)loadFixture($('#studioSkeleton')?.value||'radial');app.history.begin(`Recipe ${COMMON_FLOWER_RECIPE.name}`);try{const report=engine.execute(COMMON_FLOWER_RECIPE.id,{document:app.doc,inputs:studio.currentFixture.inputs,parameters:{fillHue:$('#recipeFill')?.value||'#cf6e82',texture:+($('#recipeTexture')?.value||14),contrast:+($('#recipeContrast')?.value||8)},...options});app.history.commit();studio.lastExecutionId=report.id;app.spatialDirty=true;app.refreshAll();app.fitContent();status(`Recipe 完成 · ${report.states.length} 狀態 · ${report.warnings.length} warning · ${report.result.documentHash}`);return report;}catch(e){app.history.cancel();status(`Recipe 拒絕／回滾：${e.message}`,'fail');throw e;}};
  const selectedPaths=()=>app.selectedObjects().map(x=>x.object).filter(o=>o.type==='path');
  const doBoolean=operation=>{const paths=selectedPaths();if(paths.length<2)throw new Error('請先選取至少兩個 Path');const layer=app.layer();app.history.pushScoped(`Boolean ${operation}`,[app.layerObjectsPath(layer)],()=>{const result=operation==='divide'?dividePaths(paths,{name:'Divide result'}):booleanPaths(paths,operation,{name:`${operation} result`});layer.objects=layer.objects.filter(o=>!paths.includes(o));if(result.type==='group')layer.objects.push(...result.children);else layer.objects.push(result);const created=result.type==='group'?result.children:[result];app.selection=created.map(object=>({layerId:layer.id,objectId:object.id}));});app.spatialDirty=true;app.refreshAll();status(`Boolean ${operation} 已產生可編輯 Compound Path`);};
  const addVectorMask=()=>{const paths=selectedPaths();if(!paths[0])throw new Error('請先選取 Path');const found=app.selectedObjects().find(item=>item.object===paths[0]);app.history.pushScoped('加入 Path 遮罩',[app.objectPath(found)],()=>{paths[0].mask=createVectorMask(paths[0],{invert:false,feather:0,expand:0});});app.renderer.render();app.refreshAll();status('物件 Mask 已依真實 Path 邊界運作');return paths[0].mask;};
